ruleToc.chapterList:
@js:
var arr = (JSON.parse(src).data) || [];
// 语言优先级（数字越小越优先）
var pri = {zh:0, 'zh-hk':1, 'zh-tw':1, en:2};
function rank(l){ var r = pri[l]; return (r === undefined) ? 9 : r; }
// 按话聚合
var groups = {};
var order = [];
for (var i=0;i<arr.length;i++){
    var c = arr[i];
    var a = c.attributes || {};
    var ch = (a.chapter === null || a.chapter === undefined) ? '?' : String(a.chapter);
    if (!groups[ch]) { groups[ch] = []; order.push(ch); }
    groups[ch].push({ id: c.id, lang: a.translatedLanguage || '?', up: a.updatedAt || '' });
}
var lists_ = [];
for (var k=0;k<order.length;k++){
    var ch = order[k];
    var items = groups[ch];
    // 语言优先排序
    items.sort(function(x,y){ return rank(x.lang) - rank(y.lang); });
    var langs = [];
    for (var j=0;j<items.length;j++){ if (langs.indexOf(items[j].lang) < 0) langs.push(items[j].lang); }
    // 标题：话号 + 语言标签（中文特别标注）
    var label = langs.map(function(l){
        var n = getLanguage(l);
        return (rank(l) === 0 || rank(l) === 1) ? ('【' + n + '】') : n;
    }).join('/');
    // 主译本 = 优先级最高
    var main = items[0];
    lists_.push({
        title: '第' + ch + '话  ' + label,
        url: 'https://api.mangadex.org/at-home/server/' + main.id + '?forcePort443=false',
        info: formatDate(main.up) + ' | ' + getLanguage(main.lang)
    });
}
if (lists_.length === 0) { java.longToast('本书暂无正文章节（可能尚未更新或已被下架）'); }
lists_;

